"""Guide copy shared by the route table, guide index and article renderer."""
from html import escape

UPDATED = '2026-11-09'
GUIDES = [
 dict(slug='windows-rdp-iphone-ipad', title='Connect to a Windows desktop from iPhone or iPad with RDP', description='Set up a supported Windows RDP host, add it to GlanceVNC, check its certificate and troubleshoot your first connection.', sections=[
 ('requirements', 'Check the Windows computer first', '''<p>GlanceVNC connects directly to a Windows computer running an RDP server. You need an iPhone or iPad with iOS or iPadOS 18 or later, a reachable computer and a Windows account allowed to sign in remotely.</p><p>Windows Pro, Enterprise, Education and Windows Server can host Remote Desktop. Windows Home cannot host the built-in RDP service. Check the edition before troubleshooting the app. Keep the computer powered on and awake.</p>'''),
 ('windows', 'Enable Remote Desktop', '''<ol><li>On Windows, open Settings → System → Remote Desktop and turn Remote Desktop on.</li><li>Keep Network Level Authentication enabled. Confirm your account is allowed under Remote Desktop users.</li><li>Note the computer’s reachable IP address or hostname. Confirm its firewall permits RDP from your trusted network or VPN.</li></ol><p>For the first connection, place both devices on the same trusted network. For access away from home, use your own VPN and its reachable computer address.</p>'''),
 ('connection', 'Add the RDP connection in GlanceVNC', '''<ol><li>Open Saved Connections and choose Add Connection (+).</li><li>Select RDP as the protocol. Give the connection a recognisable name.</li><li>Enter the Windows computer’s address and its RDP port, normally 3389. Set Operating System to Windows.</li><li>Enter the username and account password supplied for that computer. A Windows Hello PIN is not the account password.</li><li>Save and connect. When certificate review is required, verify the certificate details with the administrator before approving.</li></ol><p>RDP hosts must be added manually: Nearby Connections discovers VNC services. Certificate approval is remembered; a changed certificate requires review again. Optional strict certificate security requires successful verification and offers no approval override.</p>'''),
 ('limits', 'What works in the session', '''<p>GlanceVNC supports direct TLS/NLA RDP connections with username/password sign-in, desktop display, keyboard and pointer input, scrolling and plain-text clipboard exchange. Use Touch or Trackpad controls and Fit whole desktop or Fill screen as needed.</p><p>RDP gateways, Kerberos/Azure sign-in, audio and file/device redirection are not supported. Clipboard exchange handles text, not files. If your organisation requires a gateway or a different sign-in method, this direct setup does not meet that requirement.</p>'''),
 ('troubleshooting', 'If the desktop does not appear', '''<p>A timeout usually calls for checking the address, network route, firewall and whether the PC is awake. A rejected sign-in calls for checking the account password, username format and remote access permissions. Ask the administrator to verify certificate changes rather than accepting an unexplained replacement.</p><p>See <a href="/guides/vnc-vs-rdp/">VNC versus RDP</a> for protocol selection and <a href="/support.html">support</a> for session controls.</p><p>Windows setup reference: <a href="https://learn.microsoft.com/windows-server/remote/remote-desktop-services/remotepc/remote-desktop-allow-access">Microsoft’s Remote Desktop instructions</a>.</p>''')]),
 dict(slug='raspberry-pi-vnc-iphone-ipad', title='Access a Raspberry Pi desktop from iPhone or iPad', description='Prepare a compatible Raspberry Pi VNC desktop, connect with GlanceVNC and separate network problems from authentication problems.', sections=[
 ('requirements', 'Choose a compatible desktop server', '''<p>To see a Raspberry Pi desktop in GlanceVNC, the Pi must run a graphical desktop and a compatible VNC server. GlanceVNC is the viewer on your iPhone or iPad; it does not install or start a desktop server on the Pi. Raspberry Pi OS Lite does not include a graphical desktop.</p><p>VNC server defaults vary across Raspberry Pi OS releases and display systems. Do not assume every WayVNC or RealVNC configuration is compatible. GlanceVNC supports standard VNC password authentication and certificate-backed VeNCrypt 0.2 X509None, X509Vnc and X509Plain modes. Tight Security and anonymous TLS are not supported.</p>'''),
 ('server', 'Prepare the Pi', '''<ol><li>On the Pi, check the installed OS, desktop and VNC server. Follow the Raspberry Pi documentation for enabling VNC on that release.</li><li>Configure an authentication mode supported by GlanceVNC. If the server cannot offer one, use a compatible VNC server configuration rather than weakening an unrelated security setting.</li><li>Note the listening port and reachable IP address. <code>hostname -I</code> on the Pi shows its network addresses; choose the address for the network you are using.</li><li>Keep the desktop session available. For headless use, configure a desktop resolution using the instructions for your OS and server.</li></ol><p>The <a href="https://www.raspberrypi.com/documentation/computers/remote-access.html">official Raspberry Pi remote access documentation</a> explains the current OS options. Raspberry Pi Connect is a separate service, not a connection type inside GlanceVNC.</p>'''),
 ('connect', 'Save the connection on iPhone or iPad', '''<ol><li>Connect both devices to the same trusted network. Allow GlanceVNC Local Network access when prompted.</li><li>In Saved Connections, choose Add Connection (+), select VNC and set Operating System to Linux.</li><li>Enter the Pi’s address and VNC port, commonly 5900. A server using display :1 may listen on 5901; use the server’s actual port.</li><li>Choose the sign-in method matching the server and enter its credentials. A VNC password can be separate from your Linux login password.</li><li>Save and connect. Confirm that the desktop appears and accepts pointer and keyboard input.</li></ol><p>For certificate-backed VeNCrypt, configure the trust material required by the server. Standard password-only VNC does not encrypt the desktop stream; use it only on a trusted network or through your own VPN.</p>'''),
 ('remote', 'Connect from away and diagnose failures', '''<p>Prove the local connection first. Then connect both devices through your own VPN, allow access to the Pi’s VNC port and use the Pi address reachable over that VPN. There is no GlanceVNC relay or built-in Raspberry Pi cloud sign-in.</p><p>If the connection times out, check the service, port, firewall and network route. If authentication is rejected, compare the offered security mode with the supported modes above. If a connection opens without a desktop, check that a graphical session and headless resolution exist on the Pi.</p><p>For server compatibility details, see <a href="/support.html">GlanceVNC support</a>. For a command-line workflow rather than a desktop, explore <a href="https://glancessh.com/guides/linux-ssh-iphone-ipad/">SSH connections with GlanceSSH</a>, a separate app.</p>''')]),
 dict(slug='vnc-vs-rdp', title='VNC or RDP: which should you use on iPhone and iPad?', description='Compare GlanceVNC’s VNC and RDP support, computer requirements, security and limitations before choosing a connection type.', sections=[
 ('choose', 'Start with the server your computer provides', '''<p>Use VNC for a compatible Mac Screen Sharing or Linux VNC desktop. Use RDP for a supported Windows Remote Desktop host or compatible Linux RDP server. GlanceVNC supports both protocols on iPhone and iPad, but the computer must already provide the service you select.</p><p>The protocols are not interchangeable: selecting RDP does not turn a VNC server into an RDP server. Both need a reachable network address, correct port and supported sign-in method.</p>'''),
 ('comparison', 'Compare the supported paths', '''<div class="guide-table-wrap"><table><caption>VNC and RDP in GlanceVNC</caption><thead><tr><th scope="col">Question</th><th scope="col">VNC</th><th scope="col">RDP</th></tr></thead><tbody><tr><th scope="row">Common use</th><td>Mac Screen Sharing, Linux or Raspberry Pi with a compatible server</td><td>Windows Remote Desktop or compatible Linux RDP</td></tr><tr><th scope="row">Typical port</th><td>5900; confirm the server setting</td><td>3389; confirm the server setting</td></tr><tr><th scope="row">Nearby discovery</th><td>Bonjour-advertised VNC services</td><td>Add the host manually</td></tr><tr><th scope="row">Sign-in</th><td>Standard VNC password, supported legacy Apple authentication or compatible X.509 VeNCrypt</td><td>Direct TLS/NLA with username and password</td></tr><tr><th scope="row">Transport</th><td>Encryption depends on the server and selected mode</td><td>TLS</td></tr><tr><th scope="row">Clipboard</th><td>Plain text on compatible servers</td><td>Plain text</td></tr></tbody></table></div>'''),
 ('security', 'Understand the security differences', '''<p>Do not assume every VNC connection is encrypted. Optional strict VNC security needs a compatible certificate-backed VeNCrypt 0.2 server; standard Mac Screen Sharing does not provide that mode. For a password-only VNC server, use a trusted network or your own VPN.</p><p>RDP uses TLS. Check certificate details before giving a new approval, and investigate unexpected changes. Optional strict certificate verification blocks failures rather than allowing an approval override or unencrypted fallback.</p><p>Neither protocol creates an internet route by itself. Away-from-home connections still need your own reachable network path, normally a VPN for these guides.</p>'''),
 ('limits', 'Check the app’s limits before choosing', '''<p>GlanceVNC’s RDP support does not include gateways, Kerberos/Azure sign-in, audio or file/device redirection. VNC does not support newer Apple Screen Sharing authentication, Tight Security or anonymous TLS. Neither protocol’s clipboard support transfers files or images.</p><p>Both provide remote pointer and keyboard input, Touch and Trackpad modes, zoom and display preferences. The available desktop resolution depends on the server; Mac Screen Sharing retains the Mac’s display resolution. Choose based on the server, authentication and workflow you need, rather than an unsupported claim that one protocol is always faster.</p>'''),
 ('next', 'Follow the matching setup guide', '''<ul><li><a href="/guides/mac-mini-ipad-vnc-tailscale/">Mac mini with VNC and Tailscale</a></li><li><a href="/guides/windows-rdp-iphone-ipad/">Windows with RDP</a></li><li><a href="/guides/raspberry-pi-vnc-iphone-ipad/">Raspberry Pi with a compatible VNC server</a></li></ul><p>The <a href="/support.html">support FAQ</a> lists detailed protocol and session compatibility.</p>''')]),
 dict(slug='mac-screen-sharing-authentication', title='Troubleshoot Mac Screen Sharing authentication in GlanceVNC', description='Check the VNC password, supported Apple authentication, local network access and desktop preparation when Mac Screen Sharing will not connect.', sections=[
 ('identify', 'Identify which stage is failing', '''<p>For the simplest compatible Mac Screen Sharing setup, enable a dedicated VNC password on the Mac and select VNC password in GlanceVNC. That password can differ from your Mac account password. A network timeout, a rejected password and a desktop that never appears require different checks.</p><p>Start on the same trusted local network. Once the local connection works, move to your own VPN for access away from home. This separates server configuration from remote network routing.</p>'''),
 ('mac', 'Check Screen Sharing on the Mac', '''<ol><li>Open System Settings → General → Sharing and inspect Screen Sharing. Remote Management and Screen Sharing cannot both be enabled; consult the administrator before changing a managed Mac.</li><li>In the Screen Sharing settings, enable VNC viewers may control screen with password and set a dedicated password.</li><li>Keep the Mac awake and note its current network address.</li></ol><p>Control names vary by macOS release. Refer to <a href="https://support.apple.com/guide/mac-help/turn-screen-sharing-on-or-off-mh11848/mac">Apple’s Screen Sharing guide</a> for the controls on your Mac.</p>'''),
 ('app', 'Match the saved connection to the server', '''<ol><li>Edit the GlanceVNC connection and select VNC, not RDP. Enter the Mac address and the server port, normally 5900.</li><li>Set Operating System to Mac so hardware keyboard shortcuts use remote Command.</li><li>Under Sign In → Method, choose VNC password. Leave Username blank for this method and use the dedicated VNC password.</li><li>Save and reconnect. If iOS asks for Local Network permission, allow it for local discovery and access.</li></ol><p>GlanceVNC supports compatible legacy Apple Remote Desktop authentication when offered, but not newer Apple Screen Sharing authentication. Entering an Apple Account password will not add support for an unsupported server mode.</p>'''),
 ('errors', 'Use the symptom to choose the next check', '''<h3>Timeout or unreachable computer</h3><p>Check the Mac’s address, power state, Screen Sharing service and firewall. Guest Wi-Fi can isolate devices. Nearby discovery requires a locally advertised Bonjour VNC service; try a manually entered address if discovery is unavailable.</p><h3>Password or security type rejected</h3><p>Recheck the selected sign-in method and dedicated password. Tight Security and anonymous TLS are unsupported. Standard Mac Screen Sharing does not offer the certificate-backed VeNCrypt mode needed for strict VNC security.</p><h3>Connected, but no desktop</h3><p>Mac Screen Sharing may take time to supply initial desktop dimensions. GlanceVNC waits up to 30 seconds and retries once after a preparation timeout. If it still fails, inspect the Mac’s sharing and display state and record the exact error.</p>'''),
 ('remote', 'Retest through your VPN', '''<p>Once local access works, activate your VPN on both ends, check its access rules and change the saved host to the Mac’s VPN-reachable address. Keep the working VNC port and credentials. Do not expose the password-only VNC service directly to the public internet.</p><p>Follow the <a href="/guides/mac-mini-ipad-vnc-tailscale/">Mac mini and Tailscale walkthrough</a> for that network setup. If you contact <a href="/support.html">support</a>, include app and OS versions, sign-in method and error text, with passwords and private addresses removed.</p>''')])]

def article(guide):
    contents = ''.join(f'<li><a href="#{sid}">{escape(title)}</a></li>' for sid,title,_ in guide['sections'])
    sections = ''.join(f'<section id="{sid}"><h2>{escape(title)}</h2>{body}</section>' for sid,title,body in guide['sections'])
    related = ''.join(f'<li><a href="/guides/{g["slug"]}/">{escape(g["title"])}</a></li>' for g in GUIDES if g is not guide)
    return f'''<main id="main" class="reading-container"><article class="guide-article"><nav class="guide-breadcrumb" aria-label="Breadcrumb"><a href="/">Home</a> / <a href="/guides/">Guides</a></nav><header class="guide-heading"><h1>{escape(guide['title'])}</h1><p class="guide-intro">{escape(guide['description'])}</p><p class="guide-meta">By Chris Russell, GlanceVNC developer · Updated <time datetime="{UPDATED}">9 November 2026</time></p></header><nav class="guide-contents" aria-label="On this page"><h2>In this guide</h2><ol>{contents}</ol></nav><figure class="guide-capture"><img src="/assets/ipad-saved-connections.jpg" width="1600" height="1200" loading="lazy" alt="GlanceVNC Saved Connections on iPad showing example VNC and RDP destinations"><figcaption>Saved Connections in GlanceVNC on iPad. Example destinations shown.</figcaption></figure>{sections}<section><h2>Related guides</h2><ul>{related}</ul><p><a href="/guides/">All remote desktop guides</a></p></section></article></main>'''
